export const version: string;
export function createElement(
  type: any,
  props?: any,
  ...children: any[]
): { type: any; props: any };

declare global {
  namespace JSX {
    interface Element {
      type: any;
      props: any;
      key?: any;
    }
    interface IntrinsicElements {
      [name: string]: any;
    }
  }
}
